<?php
declare(strict_types=1);
require_once __DIR__.'/../src/Kernel.php';
require_once __DIR__.'/../src/Commerce.php';
use Zenith\{Kernel,Commerce,ApiError};
$configPath=$argv[1]??getenv('ZENITH_TEST_CONFIG');
if(!$configPath||!is_file($configPath))throw new RuntimeException('Provide an isolated test config path.');
$config=require $configPath;
if(($config['environment']??'')!=='test')throw new RuntimeException('Refusing integration fixtures outside environment=test.');
$config['session_enabled']=false;$config['pricing_min_margin_bps']=2000;$config['pricing_approval_reference']='TEST ONLY approved fixture';$config['manual_payments_enabled']=true;$config['manual_payment_approval_reference']='TEST ONLY manual fixture';
$k=new Kernel($config);$module=new Commerce($k);$now=$k->now();$suffix=$k->id();$count=0;
function check(bool $v,string $message):void{global$count;if(!$v)throw new RuntimeException($message);$count++;}
function denied(callable $fn,int $status,string $message):void{try{$fn();}catch(ApiError $e){check($e->status===$status,$message.' expected '.$status.' got '.$e->status);return;}throw new RuntimeException($message.' unexpectedly allowed');}
function actor(Kernel $k,string $id):void{$k->user=$k->publicUser($k->one('SELECT * FROM users WHERE id=?',[$id]));}
function user(Kernel $k,string $role,string $suffix,string $now):string{$id=$k->id();$k->execute('INSERT INTO users (id,name,email,password_hash,role,email_verified_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?)',[$id,'Test '.$role,$role.'-'.$suffix.'@example.invalid',password_hash(bin2hex(random_bytes(16)),PASSWORD_DEFAULT),$role,$now,$now,$now]);return $id;}
$customer=user($k,'customer',$suffix,$now);$other=user($k,'customer','other-'.$suffix,$now);$ops=user($k,'operations',$suffix,$now);$partner=user($k,'partner',$suffix,$now);
$measurement=$k->id();$design=$k->id();
$k->execute('INSERT INTO measurements (id,user_id,name,garment,unit,values_json,provenance,consent_at,verified_at,verified_by,verification_evidence,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',[$measurement,$customer,'Test measurements','suit','cm','{"chest":100,"waist":80,"hip":95,"shoulder":40,"sleeve":60,"inseam":75}','self',$now,$now,$ops,'Test professional verification',$now]);
$spec=json_encode(['garment'=>'suit','shade'=>'midnight','fit'=>'Tailored','finish'=>'Minimal','notes'=>'Test fixture'],JSON_THROW_ON_ERROR);
$k->execute('INSERT INTO designs (id,user_id,name,status,specification,measurement_id,revision,submitted_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?)',[$design,$customer,'Test design','submitted',$spec,$measurement,1,$now,$now,$now]);
actor($k,$ops);$module->handle('POST',"/designs/$design/review",['decision'=>'approved','notes'=>'Test supplier feasibility approved']);
$input=['design_id'=>$design,'lines'=>[['label'=>'Test approved garment','quantity'=>1,'unit_minor'=>10000,'cost_minor'=>6000]],'tax_bps'=>1300,'deposit_minor'=>3000,'expires_at'=>gmdate('Y-m-d\TH:i:s\Z',time()+86400),'delivery_terms'=>'Test supplier-approved delivery commitment','terms'=>'Test only approved commercial terms','approval_reference'=>'TEST ONLY approval record'];
$quote1=$module->handle('POST','/quotes',$input);$quote2=$module->handle('POST','/quotes',$input);
check($quote2['version']===2,'Sequential immutable quote versions');
actor($k,$customer);$quotes=$module->handle('GET','/quotes',[]);$visible=array_values(array_filter($quotes,fn($q)=>$q['id']===$quote2['id']))[0];
check(!isset($visible['estimated_cost_minor'])&&!isset($visible['lines'][0]['cost_minor']),'Customer quote omits internal costs');
denied(fn()=>$module->handle('POST','/quotes/'.$quote1['id'].'/approve',['accept_terms'=>true]),409,'Superseded quote rejected');
denied(fn()=>$module->handle('POST','/quotes/'.$quote2['id'].'/approve',['accept_terms'=>false]),422,'Terms required');
$order=$module->handle('POST','/quotes/'.$quote2['id'].'/approve',['accept_terms'=>true]);$oid=$order['id'];
check($order['total_minor']===11300&&$order['status']==='awaiting_payment','Accepted quote creates genuine unpaid order');
$again=$module->handle('POST','/quotes/'.$quote2['id'].'/approve',['accept_terms'=>true]);check($again['id']===$oid,'Approval retry creates no duplicate order');
check((int)$k->one('SELECT COUNT(*) count FROM invoices WHERE order_id=?',[$oid])['count']===1,'Exactly one immutable invoice');
actor($k,$other);denied(fn()=>$module->handle('GET','/orders/'.$oid,[]),404,'Cross-customer order isolation');
actor($k,$partner);denied(fn()=>$module->handle('GET','/orders',[]),403,'Partner cannot browse unrelated orders');
actor($k,$ops);denied(fn()=>$module->handle('POST',"/orders/$oid/transition",['status'=>'paid','note'=>'attempt fake payment','evidence'=>'not payment']),409,'Manual status cannot mark paid');
$payment=['amount_minor'=>3000,'kind'=>'deposit','reference'=>'test-deposit-'.$suffix,'evidence'=>'Test externally verified deposit receipt'];
$p=$module->handle('POST',"/orders/$oid/manual-payment",$payment);check($p['order']['status']==='deposit_received','Evidence-backed deposit updates payment state');
$dup=$module->handle('POST',"/orders/$oid/manual-payment",$payment);check(($dup['duplicate']??false)===true,'Duplicate reference idempotent');
check((int)$k->one('SELECT SUM(amount_minor) total FROM payments WHERE order_id=?',[$oid])['total']===3000,'Duplicate payment not double counted');
denied(fn()=>$module->handle('POST',"/orders/$oid/manual-payment",array_replace($payment,['amount_minor'=>1000])),409,'Reference cannot mutate amount');
denied(fn()=>$module->handle('POST',"/orders/$oid/manual-payment",array_replace($payment,['reference'=>'too-much-'.$suffix,'kind'=>'balance','amount_minor'=>9000])),422,'Overpayment rejected');
$module->handle('POST',"/orders/$oid/transition",['status'=>'production_preparation','note'=>'Deposit reconciled','evidence'=>'Approved quote and verified receipt']);
denied(fn()=>$module->handle('POST',"/orders/$oid/transition",['status'=>'in_production','note'=>'Attempt without supplier','evidence'=>'No job yet']),409,'Supplier work order required');
$module->handle('POST',"/orders/$oid/production",['supplier_reference'=>'TEST ONLY supplier','specification'=>'Test approved supplier handoff instructions','acknowledgement'=>'Test supplier acknowledged','due_at'=>gmdate('Y-m-d H:i:s',time()+604800)]);
$module->handle('POST',"/orders/$oid/transition",['status'=>'in_production','note'=>'Supplier acknowledged','evidence'=>'Test signed work order']);
$module->handle('POST',"/orders/$oid/transition",['status'=>'quality_inspection','note'=>'Production complete','evidence'=>'Test completion evidence']);
$module->handle('POST',"/orders/$oid/qc",['result'=>'pass','report'=>'Test initial inspection passed','evidence'=>'Test QC photos']);
$module->handle('POST',"/orders/$oid/qc",['result'=>'fail','report'=>'Test later inspection failed','evidence'=>'Test defect report']);
denied(fn()=>$module->handle('POST',"/orders/$oid/transition",['status'=>'shipping_preparation','note'=>'Attempt skip defect','evidence'=>'Old QC pass']),409,'Latest failing QC blocks shipment');
$module->handle('POST',"/orders/$oid/qc",['result'=>'pass','report'=>'Test rework inspection passed','evidence'=>'Test corrected QC photos']);
$module->handle('POST',"/orders/$oid/transition",['status'=>'shipping_preparation','note'=>'Final QC approved','evidence'=>'Latest QC pass']);
denied(fn()=>$module->handle('POST',"/orders/$oid/transition",['status'=>'in_transit','note'=>'Try without shipping','evidence'=>'No tracking']),409,'Tracking required');
$module->handle('POST',"/orders/$oid/shipments",['carrier'=>'Test carrier','tracking'=>'Test tracking','stage'=>'dispatched','note'=>'Test dispatch recorded']);
$module->handle('POST',"/orders/$oid/transition",['status'=>'in_transit','note'=>'Test shipment dispatched','evidence'=>'Test carrier receipt']);
$module->handle('POST',"/orders/$oid/transition",['status'=>'arrived_canada','note'=>'Test import arrival','evidence'=>'Test clearance receipt']);
denied(fn()=>$module->handle('POST',"/orders/$oid/transition",['status'=>'ready_for_delivery','note'=>'Try without balance','evidence'=>'Deposit only']),409,'Balance required before delivery');
$balance=$module->handle('POST',"/orders/$oid/manual-payment",['amount_minor'=>8300,'kind'=>'balance','reference'=>'test-balance-'.$suffix,'evidence'=>'Test externally verified balance receipt']);
check($balance['order']['status']==='arrived_canada','Late balance payment preserves manufacturing progress');
$module->handle('POST',"/orders/$oid/transition",['status'=>'ready_for_delivery','note'=>'Test ready for handover','evidence'=>'Balance and QC complete']);
$module->handle('POST',"/orders/$oid/transition",['status'=>'delivered','note'=>'Customer received garment','evidence'=>'Test customer receipt']);
$module->handle('POST',"/orders/$oid/transition",['status'=>'completed','note'=>'Test customer accepted fit','evidence'=>'Test acceptance record']);
$module->handle('POST',"/orders/$oid/expenses",['category'=>'manufacturing','amount_minor'=>6000,'evidence'=>'Test supplier invoice']);
$work=$module->handle('GET',"/orders/$oid/work-order",[]);check(isset($work['approved_specification']['measurement']),'Supplier document uses locked measurement snapshot');
actor($k,$customer);$detail=$module->handle('GET',"/orders/$oid",[]);check(!isset($detail['expenses'])&&$detail['production']===null&&$detail['qc']===[],'Customer detail hides internal operations and costs');check(!isset($detail['history'][0]['evidence'])&&!isset($detail['payments'][0]['evidence']),'Customer history hides private financial evidence');
actor($k,$ops);denied(fn()=>$module->handle('POST',"/orders/$oid/refunds",['amount_minor'=>20000,'reason'=>'Test invalid excessive refund','reference'=>'refund-too-high-'.$suffix,'evidence'=>'Test receipt']),422,'Refund cannot exceed verified collection');
$refund=['amount_minor'=>1000,'reason'=>'Test approved partial correction','reference'=>'test-refund-'.$suffix,'evidence'=>'Test externally verified refund receipt'];$r=$module->handle('POST',"/orders/$oid/refunds",$refund);$r2=$module->handle('POST',"/orders/$oid/refunds",$refund);check(($r2['duplicate']??false)===true,'Refund retry is idempotent');
check($r['order']['refunded_minor']===1000&&$r['order']['net_paid_minor']===10300,'Refund reconciles actual funds');
$reports=$module->handle('GET','/reports',[]);$row=array_values(array_filter($reports['orders'],fn($x)=>$x['order_id']===$oid))[0];check($row['recorded_variable_expenses_minor']===6000,'Unit economics use actual expense records');
echo "PASS $count commerce integration assertions; fixture order $oid\n";
